import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"遯","description":"高岛易断 - 遯","frontmatter":{"title":"遯","description":"高岛易断 - 遯"},"headers":[],"relativePath":"zh/classics/takashima/033.md","filePath":"zh/classics/takashima/033.md"}'),i={name:"zh/classics/takashima/033.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="遯" tabindex="-1">遯 <a class="header-anchor" href="#遯" aria-label="Permalink to “遯”">​</a></h1><h2 id="遯-1" tabindex="-1">遯 <a class="header-anchor" href="#遯-1" aria-label="Permalink to “遯”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>遁：亨，小利贞。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《遁》，阴长之卦，小人方进，君子道消。邪正不同居，阴阳不两立，君子当此，若不隐遁，必受其害。当《遁》而遁，遁而后通，故曰“遁亨”。“小利贞”者，小指二阴而言也，谓阴道始长，阳道犹未全消，故曰“小利贞”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>天下有山，遁，君子以远小人，不恶而严。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>“天下有山，遁”，天之与山，相去辽远，不可几及，是天远山，非山远天，在山亦不能怨天之远也。君子则之，以远小人，不必显出恶言，亦未尝始示和气，但望之而自觉可畏，即之俨然难犯，使小人不远而自远也。“不恶而严”，斯为待小人之善法也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问战征：防前进有山，山间有敌兵埋伏，致遭败北。</p><p>○　问营商：恐一时物价涨落不同，相去甚远。</p><p>○　问功名：宜退隐，不宜进见。君子吉，小人否。</p><p>○　问家宅：此宅近山，前面空阔辽远，防有阴崇。</p><p>○　问疾病：病有鬼祟，宜敬而远之，以避居为吉。</p><p>○　问婚姻：二五阴阳，本属相应，但邪正不同，以谢绝之为吉。</p><p>○　问六甲：生女。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初爻居《艮》之始，《艮》为穴居，又为尾，故曰“遁尾”。贤者避地，入山惟恐不深，入林惟恐不密，不欲使人尾其后也。若乃《遁》而不藏其尾，非真《遁》也，是殆借名山为捷径，欲藉《遁》以为攸往计耳。古今来高隐不终，不特为猿鹤贻笑，而功犹未成，失即随之，其危厉，皆自取之耳。故戒之曰“勿用有攸往”，谓其宜遁而不宜往也。《象传》曰：“不往何灾”，盖往则灾来，不往则无灾，反言之以阻其往也。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问战征：为伏兵言也。埋伏宜深藏不露，使敌不得窥其遗迹，若藏头露尾，必致危厉，不如不往也。</p><p>○　问营商：销卖货物，宜赶快，不宜落后，并宜首尾一并卖讫，斯可免灾。</p><p>○　问功名：龙门烧尾，吉。</p><p>○　问家宅：宜速迁移，落后有灾。</p><p>○　问婚姻：《遁》者，避而远之之谓，婚姻不合。</p><p>○　问六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某来，请占气运，筮得《遁》之《同人》。</p><p>断曰：《遁》卦四阳在外，二阴在内，在外者阳浸而消，在内者阴浸而长。运以得阳为佳，阳消阴长，是好运已退也。今占得《遁》初爻，初爻以阳居阴，爻辞曰“遁尾，厉，勿用有攸往”，谓好运既退，第留此尾末而已，故“厉”。戒曰“勿用”，是宜退守，毋前往也。运以五年为一度，至上六，则“无不利”矣。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“执之”，“莫之”，两“之”字，皆指《遁》者言。黄，中央之正色，牛性柔顺，革性坚韧。《艮》为皮，故曰“革”；《艮》为手，故曰“执”；二得《坤》气，《坤》为黄牛，故曰“黄牛”。二居内爻，为成卦之主，上应九五，阴长阳消，应五而实消五，五即因之而《遁》，诸爻亦相随遁去。二爻欲执而留之，如白驹之诗，所咏“执之维之”者是也。“执之用黄牛之革”，以拟其执留之坚，而莫之遁焉。“胜”者，堪也，“说”者，解脱也，“莫之胜脱”，使之不可逃脱也。诸爻皆言《遁》，二爻独不言《遁》，《遁》者诸爻，而驱之使《遁》者，二爻也；二既驱之使《遁》，而复欲假意以执之，不令其遁，是小人牢笼之计也。《象传》曰“固志”，五之《象》曰“正志”，二五之志本不同。二欲藉嘉会之礼，以笼络五之志，使之不遁，“固志”者，固五之志也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问战征：当诸军逃散之际，独能坚执固守，为可嘉也。</p><p>○　问营商：固一时货价逐涨，执守来本，莫能脱售。</p><p>○　问功名：席珍待聘，美玉待沽，功名之兆也。“莫之胜脱”，功名难望矣。</p><p>○　问家宅：此宅阴气渐盛，居者不利，群思迁移，即欲脱售，一时亦难。</p><p>○　问婚姻：此婚已成，后欲退悔，执柯者甚属为难。</p><p>○　问六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>友人某，来请占气运，筮得《遁》之《姤》。</p><p>断曰：此卦二阴浸长，四阳浸衰，阴者小人，阳者君子，小人日进，君子日退，故谓之《遁》。以气运言之，正是运退之时也。“黄牛之革”，物之又软又韧者，以此系物，物莫能脱，譬言人生为运所缚，虽有志愿，终生捆缚，不克施展。今占二爻，其象如此，运可知矣。</p><p>明治二十九年，占皇国气运，筮得《遁》之《姤》。</p><p>断曰：此卦四阳为二阴所侵，论人事则我为彼所侵，于国亦然。自我国胜清之后，俄、德、法三国，以亚细亚之乎和为口实，使我还付辽东，加之俄法为清国偿金斡旋，俄清之交一变，将有事于东洋。方今欧洲诸强国，皆惟竞利自图，约束清国，譬如用“黄牛之革”，絷缚其手足，使之莫能解脱，几欲瓜分之以为快。而于我国，亦未尝不欲以此相缚，我惟固守其志，内修军备，外善辞令，以敦邦交，而不受此笼络也。此为得计耳。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“系”者，羁绊之义。三以阳刚，居内卦之上，与二阴阳相亲比，为二所羁縻，不忍超然远引，欲《遁》而志不决，故曰“系遁”。凡当《遁》则《遁》，贵速而远，一有所系，则忧愁莫定，宛如疾痛之在身，危厉之道也，故曰“有疾厉”。盖“系”者，三系于二，阴为之主；“畜”者，二畜于三，阳为之主。以阴系阳则厉，以阳畜阴则吉。“臣妾”者阴象，三阳在二阴之上，故能畜。君子之于臣妾，畜之以供使令，进退无足关重轻也，是以“系遁”不失为吉，至若当大事，必致因循而坐误也。《象传》曰：“有疾，惫也”，惫谓力竭而敝惫也。“不可大事也”，大事者，指三一生大节而言，不可或忽也。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问战征：军阵进退，皆有纪律，鼓进金退，最要便捷，一有迟误，必致大败也，宜慎。</p><p>○　问营商：货物当脱售之时，不宜踌躇不决，或系恋私情，防误大事。</p><p>○　问功名：时当奸人秉政，宜急流勇退，斯无疾害。</p><p>○　问家宅：此宅不利，主多病厄，宜速迁移，若迟延不去，恐有大祸。</p><p>○　问婚姻：娶嫡不利，娶妾则吉。</p><p>○　问六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某来，请占商业之盛衰，筮得《遁》之《否》。</p><p>断曰：三爻以阳居阳，留恋二阴，欲遁不决，致“有疾，厉”。今足下占问商业，得此三爻，知为商业失败之象，宜速脱货，则损失犹微；若惜金而踌躇，则品物之价，日益低落，其所损更大也，谓之“系遁，有疾，厉”。“畜臣妾，吉”者，谓葆此余资，以畜养家人可也，若欲重兴商业，则不可也。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四与初相应，相应必相好，乃初与四好，而四不好初；且四因初之好，而决意远遁，故曰“好遁”。然在初之好四，亦非真好，不过欲借四以为重，是引用君子之意，若新莽之礼贤下士是也。四则有见于此，不为初所笼络，而超然远引，谓尔虽好我，我不好尔，尔不我遁，我则自遁，我行我志而已。四入《乾》，《乾》为君子，故曰“君子吉”。在初之厚貌深情，以为四必感恋情好，不意室迩人远，一去千里，竟有不可执维者。初处《艮》，《艮》为小子，故曰“小人否”。一说“好遁”者，谓有所好而遁也，犹《论语》“从吾所好”之好。世人所好，在富贵功名，君子所好，在乐天知命，此谓好遁。亦通。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问战征：四处《乾》之始，《乾》为健，知进不知退。或军中有一人谋陷，故作退计以避之。退亦吉也。</p><p>○　问营商：商家以买入为进，卖出为退，四曰“好遁”，知以出货为得利也。</p><p>○　问功名：爻辞“好遁”，是其人必无意于功名也。然名亦不同，或盗虚名于一时，或垂大业于千秋，君子小人，所由分也。占者宜自审焉。</p><p>○　问疾病：四《乾》体，爻曰“好遁”，阳《遁》而入阴，其病危矣。然转危为安，亦《遁》之象，想大人可治，小人难也。</p><p>○　问婚姻：防后有离婚之忧。</p><p>○　问讼事：俗云“三十六着，走为上着”，“好遁”之谓也。</p><p>○　问六甲：生男。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>亲友某来，请占气运，筮得《遁》之《渐》。</p><p>断曰：四居《乾》阳之首，《乾》曰见，不曰隐，乃四为二阴所逼，超然远遁，是遁而避害也。今足下占得第四爻，足下躬膺职位，亦知僚属中，邪正不一，或外面情好敦笃，其中奸计百出，不可不防。足下知其然，不露声色，决意引退，是明哲保身之要道也。爻辞曰，“九四：好遁，君子吉，小人否”，谓君子飞遁离俗则吉，小人溺情爵禄则否矣。爻象如是，足下其审之。后某果因官制改革，有非职之命。</p><p>一日杉浦重刚氏来曰：方今为千岛舰事，以上海英国上等裁判所判决为不当，将再向英国理论，其结局果否？如何？请筮之。筮得《遁》之《渐》。</p><p>断曰：此卦阴长阳消，为邪强正弱之象。正者必反而受屈，卦象如是。今占千岛舰判审事，得《遁》四爻，《遁》卦二阴在内，长而逼上，至四爻则阴势已盛，阳气殆尽，在下面虽假作情好，而内心实阴险莫测。核之千岛舰之事，情形符合。我国因千岛舰失事，据万国公法向彼理论，迭经审问，终不得直。盖现今天下大势凭强弱，不凭曲直，亦事之无可如何者矣。爻辞曰“好遁”，是教我以退避也，即得退遁，了事而已。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五以阳居阳，刚健中正，虽与六二相应，能知时审势，应变识几，超然远遁。其遁也，不为情移，不为势屈，意决而志正，洵可嘉美矣，故曰“嘉遁，贞吉”。《象传》曰“以正志也”，谓九五《遁》得其正，即可以正二之志，是“不恶而严”也。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问战征：正当敌势强盛，能以潜遁而返，得保全师，亦可嘉也。</p><p>○　问营商：货到该处，时价不合，而转别地，得以获利，可谓应变而不失其正也，故吉。</p><p>○　问功名：爻以九五为尊，占得九五，是必功名显达，位近台辅。伊尹曰，“臣罔以宠利居成功”，谓能以功成身退者也，故吉。</p><p>○　问家宅：此宅必是南阳诸葛之庐，栗里陶令之宅也，高风可尚。</p><p>○　问婚姻：二五本阴阳相应，有意议婚，五以其志不同，不允。另就他聘，吉。</p><p>○　问疾病：是阴邪纠缠之症，潜而遁避，可获吉。</p><p>○　问六甲：生男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>予亲友永井泰次郎，其妻有娠，张筵招予，请卜男女，筮得《遁》之《旅》。</p><p>断曰：九五《乾》卦，以阳居阳，生男之兆也。《乾》为父，《艮》为少男，他年少男嗣父而续家，老父让产而隐居，故名此卦曰《遁》。且其辞曰“嘉遁，贞吉”，是有子克家之象。其后果生男子。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>“肥”者饶裕也。卦中诸爻，欲遁而多所系累，此爻独无应无比，故无系累，不复劳顾忌，飘然远弓，所谓进退绰有余裕者也，故曰“肥遁，无不利”。《象传》曰：“无所疑也”，谓上爻居《乾》阳之首，其察势也明，其见几也决，首先高遁》，绝无一毫之疑碍也。或谓“嘉遁”如殷微子，如汉张良，“肥遁”如泰伯、伯夷，或又如汉之商山四皓也。</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问战征：战事宜进不宜遁，遁必不利；爻曰“肥遁，无不利”，其惟太王避狄迁岐乎？</p><p>○　问营商：商人谋利，往往群焉竞逐，今独能人取我弃，以退为进，则其退反得厚利，故爻曰“肥遁”。</p><p>○　问功名：其人必不以膏梁肥口，能以道义肥躬，故曰“肥遁，无不利”。</p><p>○　问家宅：此宅地位甚高，家道亦富，但利于求财，不利于求名。</p><p>○　问疾病：肥人气虚，《遁》者，脱也，恐致虚脱。</p><p>○　问婚姻：恐女子贪恋富室子弟，因而私奔。</p><p>○　问六甲：生男。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治十八年三月，以中央亚细亚阿富汗境界事，生英狮俄鹫之葛藤，凡新闻电信所报，论和论战，主俄主英，诸说纷纷，各国皆有戒意。即如我国，利害所关，亦非浅鲜。因占其和战如何，筮得《遁》之《咸》（明治十八年五月八日）。</p><p>断曰：内卦为山，属英，外卦为天，属俄。山《艮》而止，今观英国所为，虽频修战备，不过虚张声势，其实无意于战也。何者？英之海军虽强，至如阿富汗中央亚细亚地方，不能专用海军，若陆军，在英兵数不多，仅足护国而已。且苏丹之役，已分遣陆兵不少，他如印度兵，虽派遣于阿富汗高寒之地，不能尽得其力；加之印度各分宗教，兵士各守其宗规，粗食亦不足，即驱而用之，岂能当强俄乎？故欲战不得不用海军，用海军之处，有关通商航海之障碍，可以牵动各国。即可以压制俄国，在英国无心开战，可于《艮》止而得其象也。天《乾》而健，今观俄国所为，俄国遵奉彼得帝遗训，知进而不知退，意在鲸吞各国以为快，可见俄国有意开战。合内外卦则为《遁》，是《遁》为英国之气运，《遁》反卦为《大壮》，是为俄国之气运。在英之对俄，惟有严其守备，使俄无隙可乘，即可断英俄交涉之结果也。</p>',97)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
